// Some portions generated by Claude
import type { Graph } from "./graph-types.ts";
import type { LayoutOptions } from "./graph-layout-engine.ts";
import { GraphScene } from "./graph-scene.ts";
import { graphNodeSize } from "./graph-geometry.ts";
import { separateLayoutRectangles } from "./graph-layout-overlap.ts";
import {LAYOUT_SPACING as gap} from './graph-layout-spacing.ts';

/** Bounded-memory breadth-first packing for graphs too large for dense stress matrices. */
export function computeSparseLayout(graph: Graph, options: LayoutOptions = {}) {
  if (options.incremental || options.localNodeIds?.size || options.refine || options.repairOnly) {
    const positions = new Map(graph.nodes.map(node => [node.id, {x: node.x ?? 0, y: node.y ?? 0}]));
    separateLayoutRectangles(graph, positions, {...options, repairOnly: true});
    return {positions, bends: new Map<string, number>()};
  }
  let stepX = 260, stepY = 90;
  for (const node of graph.nodes) {
    const size = options.nodeSizes?.get(node.id) ?? graphNodeSize(node);
    stepX = Math.max(stepX, size.width + gap.nodeGapX); stepY = Math.max(stepY, size.height + gap.nodeGapY);
  }
  const scene = new GraphScene(graph),
    n = graph.nodes.length;
  const order = Array.from({ length: n }, (_, i) => i).sort(
    (a, b) =>
      scene.offsets[b + 1] -
        scene.offsets[b] -
        (scene.offsets[a + 1] - scene.offsets[a]) || a - b,
  );
  const seen = new Uint8Array(n),
    queue = new Uint32Array(n),
    visit = new Uint32Array(n);
  let total = 0;
  for (const seed of order) {
    if (seen[seed]) continue;
    let read = 0,
      write = 1;
    queue[0] = seed;
    seen[seed] = 1;
    while (read < write) {
      const node = queue[read++];
      visit[total++] = node;
      for (
        let cursor = scene.offsets[node];
        cursor < scene.offsets[node + 1];
        cursor++
      ) {
        const edge = scene.incident[cursor] * 2;
        const next =
          scene.edges[edge] === node
            ? scene.edges[edge + 1]
            : scene.edges[edge];
        if (!seen[next]) {
          seen[next] = 1;
          queue[write++] = next;
        }
      }
    }
  }
  const columns = Math.max(1, Math.ceil(Math.sqrt(n * 0.38)));
  const positions = new Map<string, { x: number; y: number }>();
  const occupied = new Set<string>();
  const fixed = (i: number) =>
    graph.nodes[i].pinned ||
    Boolean(
      options.localNodeIds?.size &&
        !options.localNodeIds.has(graph.nodes[i].id),
    ) ||
    Boolean(
      options.incremental && !options.movableNodeIds?.has(graph.nodes[i].id),
    );
  for (let i = 0; i < n; i++)
    if (fixed(i)) {
      const node = graph.nodes[i];
      positions.set(node.id, { x: node.x ?? 0, y: node.y ?? 0 });
      occupied.add(
        Math.round((node.x ?? 0) / stepX) + ":" + Math.round((node.y ?? 0) / stepY),
      );
    }
  let cell = 0;
  for (let v = 0; v < n; v++) {
    const i = visit[v],
      node = graph.nodes[i];
    if (fixed(i)) continue;
    let x = 0,
      y = 0,
      key = "";
    do {
      const row = Math.floor(cell / columns),
        col = cell % columns;
      x = (row % 2 ? columns - 1 - col : col) * stepX;
      y = row * stepY;
      key = Math.round(x / stepX) + ":" + Math.round(y / stepY);
      cell++;
    } while (occupied.has(key));
    occupied.add(key);
    positions.set(node.id, { x, y });
  }
  separateLayoutRectangles(graph, positions, {...options, repairOnly: true});
  return { positions, bends: new Map<string, number>() };
}
